DELIMITER $$
CREATE TRIGGER `trg_create_wallet_after_user` AFTER INSERT ON `users` FOR EACH ROW BEGIN
        user_id,
        balance,
        currency,
        status
    )
    VALUES (
        NEW.id,
        0.00,
        'MAD',
        'active'
    );
END
$$
DELIMITER ;

